export interface Product {
  id: string
  sku: string
  name: string
  price: number
  stock: number
  status: 'Active' | 'Draft' | 'Archived'
  category: string
}

export type FieldId = 'name' | 'price' | 'stock' | 'status' | 'category'

export const fields: { id: FieldId; label: string; numeric?: boolean }[] = [
  { id: 'name', label: 'Name' },
  { id: 'price', label: 'Price', numeric: true },
  { id: 'stock', label: 'Stock', numeric: true },
  { id: 'status', label: 'Status' },
  { id: 'category', label: 'Category' },
]

/**
 * One record the bulk update touches. An update has both sides, a new record
 * only `after`, and a removal only `before`.
 */
export type Change =
  | { id: string; kind: 'update'; before: Product; after: Product }
  | { id: string; kind: 'create'; after: Product }
  | { id: string; kind: 'delete'; before: Product }

const product = (
  id: string,
  sku: string,
  name: string,
  price: number,
  stock: number,
  status: Product['status'],
  category: string,
): Product => ({ id, sku, name, price, stock, status, category })

const update = (before: Product, after: Partial<Product>): Change => ({
  id: before.id,
  kind: 'update',
  before,
  after: { ...before, ...after },
})

// A supplier price list and a stocktake, merged into one bulk update
export const changes: Change[] = [
  update(
    product('p1', 'CHR-001', 'Aero Desk Chair', 249, 34, 'Active', 'Seating'),
    {
      price: 269,
    },
  ),
  update(
    product('p2', 'CHR-014', 'Lumbar Task Chair', 189, 12, 'Active', 'Seating'),
    {
      price: 199,
      stock: 40,
    },
  ),
  update(
    product('p3', 'DSK-120', 'Oak Standing Desk', 649, 8, 'Active', 'Desks'),
    {
      price: 699,
      stock: 0,
      status: 'Archived',
    },
  ),
  update(
    product('p4', 'DSK-122', 'Walnut Standing Desk', 729, 0, 'Draft', 'Desks'),
    {
      stock: 25,
      status: 'Active',
    },
  ),
  update(
    product('p5', 'LMP-031', 'Arc Floor Lmap', 129, 51, 'Active', 'Lighting'),
    {
      name: 'Arc Floor Lamp',
    },
  ),
  update(
    product('p6', 'LMP-044', 'Task Light Mini', 59, 140, 'Active', 'Lighting'),
    {
      price: 54,
      stock: 128,
    },
  ),
  update(
    product(
      'p7',
      'STR-210',
      'Modular Shelf Unit',
      319,
      17,
      'Active',
      'Shelving',
    ),
    {
      category: 'Storage',
    },
  ),
  update(
    product('p8', 'STR-215', 'Cable Tray', 39, 300, 'Active', 'Accessories'),
    {
      price: 45,
      category: 'Storage',
    },
  ),
  {
    id: 'p9',
    kind: 'create',
    after: product('p9', 'CHR-020', 'Mesh Stool', 149, 60, 'Draft', 'Seating'),
  },
  {
    id: 'p10',
    kind: 'create',
    after: product(
      'p10',
      'ACC-310',
      'Monitor Arm',
      99,
      75,
      'Active',
      'Accessories',
    ),
  },
  {
    id: 'p11',
    kind: 'delete',
    before: product(
      'p11',
      'DSK-090',
      'Pine Writing Desk',
      279,
      0,
      'Archived',
      'Desks',
    ),
  },
]

/** Products the bulk update doesn't touch */
export const unchanged: Product[] = [
  product('u1', 'CHR-008', 'Ergo Kneeling Chair', 219, 22, 'Active', 'Seating'),
  product('u2', 'DSK-101', 'Compact Desk', 299, 41, 'Active', 'Desks'),
  product('u3', 'LMP-020', 'Clamp Desk Lamp', 79, 96, 'Active', 'Lighting'),
  product('u4', 'STR-200', 'Rolling Pedestal', 189, 30, 'Active', 'Storage'),
  product('u5', 'ACC-300', 'Desk Mat', 35, 210, 'Active', 'Accessories'),
]

/** One table row: a product, and the change waiting for it if there is one */
export interface CatalogRow {
  id: string
  /** What the catalog shows today; for a new product, what it would be */
  product: Product
  change?: Change
}

// The whole catalog in SKU order, so changed products sit among the rest
export const rows: CatalogRow[] = [
  ...unchanged.map((p) => ({ id: p.id, product: p })),
  ...changes.map((change) => ({
    id: change.id,
    product: change.kind === 'create' ? change.after : change.before,
    change,
  })),
].sort((a, b) => a.product.sku.localeCompare(b.product.sku))

import { fields } from './data'
import type { Change, FieldId, Product } from './data'

export type Decision = 'accepted' | 'rejected'

/** Decisions by change key. A key that isn't here is still pending. */
export type Decisions = Readonly<Record<string, Decision>>

// An update is decided field by field; a new or removed record as a whole
export const WHOLE = '*'
export const changeKey = (id: string, field: FieldId | typeof WHOLE) =>
  `${id}.${field}`

export function changedFields(change: Change): FieldId[] {
  if (change.kind !== 'update') return []
  return fields
    .map((f) => f.id)
    .filter((f) => change.before[f] !== change.after[f])
}

export const keysOf = (change: Change) =>
  change.kind === 'update'
    ? changedFields(change).map((f) => changeKey(change.id, f))
    : [changeKey(change.id, WHOLE)]

/** pending: nothing decided yet; partial: some of it decided; mixed: all decided, both ways */
export type RowState = 'pending' | 'partial' | 'accepted' | 'rejected' | 'mixed'

export function rowState(change: Change, decisions: Decisions): RowState {
  const made = keysOf(change).map((k) => decisions[k] as Decision | undefined)
  const pending = made.filter((d) => !d).length
  if (pending === made.length) return 'pending'
  if (pending) return 'partial'
  if (made.every((d) => d === 'accepted')) return 'accepted'
  if (made.every((d) => d === 'rejected')) return 'rejected'
  return 'mixed'
}

/** Accepts, rejects or (with null) reopens the given changes */
export function decide(
  decisions: Decisions,
  keys: string[],
  decision: Decision | null,
): Decisions {
  const next = { ...decisions }
  for (const k of keys) {
    if (decision) next[k] = decision
    else delete next[k]
  }
  return next
}

export function tally(changes: Change[], decisions: Decisions) {
  const keys = changes.flatMap(keysOf)
  const accepted = keys.filter((k) => decisions[k] === 'accepted').length
  const rejected = keys.filter((k) => decisions[k] === 'rejected').length
  return {
    total: keys.length,
    accepted,
    rejected,
    pending: keys.length - accepted - rejected,
  }
}

/**
 * The catalog after applying accepted changes only. Rejected and pending
 * changes leave the record as it was.
 */
export function apply(changes: Change[], decisions: Decisions): Product[] {
  return changes.flatMap((change): Product[] => {
    const whole = decisions[changeKey(change.id, WHOLE)]
    if (change.kind === 'create')
      return whole === 'accepted' ? [change.after] : []
    if (change.kind === 'delete')
      return whole === 'accepted' ? [] : [change.before]
    const next = { ...change.before }
    for (const f of changedFields(change)) {
      if (decisions[changeKey(change.id, f)] === 'accepted') {
        Object.assign(next, { [f]: change.after[f] })
      }
    }
    return [next]
  })
}

const money = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
})

export const formatValue = (field: FieldId, value: Product[FieldId]) =>
  field === 'price'
    ? money.format(value as number)
    : field === 'stock'
      ? (value as number).toLocaleString('en-US')
      : String(value)

/** How much a number moved: "+8.0%" for prices, "+28" for stock */
export function delta(field: FieldId, before: unknown, after: unknown) {
  if (typeof before !== 'number' || typeof after !== 'number') return null
  if (field === 'price') {
    if (before === 0) return null
    const pct = ((after - before) / before) * 100
    return `${pct > 0 ? '+' : ''}${pct.toFixed(1)}%`
  }
  const diff = after - before
  return `${diff > 0 ? '+' : ''}${diff.toLocaleString('en-US')}`
}

export type View = 'all' | 'review' | 'accepted' | 'rejected'

export const inView = (state: RowState, view: View) =>
  view === 'all' ||
  (view === 'review'
    ? state === 'pending' || state === 'partial'
    : view === 'accepted'
      ? state === 'accepted' || state === 'mixed'
      : state === 'rejected' || state === 'mixed')

export const fieldLabel = Object.fromEntries(
  fields.map((f) => [f.id, f.label]),
) as Record<FieldId, string>

export type DiffLine =
  | { kind: 'context'; field: FieldId; value: string }
  | {
      kind: 'removed' | 'added'
      field: FieldId
      value: string
      /** Set on lines that belong to a single field's change */
      key?: string
      moved?: string | null
    }

/**
 * The record as a diff: unchanged fields as context, each changed field as a
 * "-" line for the old value and a "+" line for the new one. A new product is
 * all "+", a removed one all "-".
 */
export function diffLines(change: Change): DiffLine[] {
  if (change.kind === 'create') {
    return fields.map((f) => ({
      kind: 'added',
      field: f.id,
      value: formatValue(f.id, change.after[f.id]),
    }))
  }
  if (change.kind === 'delete') {
    return fields.map((f) => ({
      kind: 'removed',
      field: f.id,
      value: formatValue(f.id, change.before[f.id]),
    }))
  }
  const changed = changedFields(change)
  return fields.flatMap((f): DiffLine[] => {
    const before = formatValue(f.id, change.before[f.id])
    if (!changed.includes(f.id)) {
      return [{ kind: 'context', field: f.id, value: before }]
    }
    const key = changeKey(change.id, f.id)
    return [
      { kind: 'removed', field: f.id, value: before, key },
      {
        kind: 'added',
        field: f.id,
        value: formatValue(f.id, change.after[f.id]),
        key,
        moved: delta(f.id, change.before[f.id], change.after[f.id]),
      },
    ]
  })
}

import { useEffect, useRef, useState } from 'react'
import type { Ref } from 'react'
import { Check, ChevronDown, ChevronUp, X } from 'lucide-react'

import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import { Checkbox } from '#/components/ui/checkbox'
import { cn } from '#/lib/utils'
import type { Change } from './data'
import { diffLines, fieldLabel, keysOf, rowState } from './diff'
import type { Decision, Decisions } from './diff'

// A card that opens at the right of the table's frame and pushes the table
// aside, so the highlighted row stays in view next to its diff. No overlay:
// the table is still there to click another row.
export function DiffPanel({
  change,
  position,
  decisions,
  onDecide,
  onPrevious,
  onNext,
  onClose,
}: {
  /** The change being reviewed; the panel is closed while this is null */
  change: Change | null
  /** "3 of 11", for the change being reviewed */
  position: { index: number; total: number }
  decisions: Decisions
  /** Decides some of this change's keys. `advance` moves on to the next change to review. */
  onDecide: (
    keys: string[],
    decision: Decision | null,
    advance?: boolean,
  ) => void
  onPrevious: () => void
  onNext: () => void
  onClose: () => void
}) {
  // Keeps the last change on screen while the panel slides out
  const [shown, setShown] = useState(change)
  if (change && change !== shown) setShown(change)

  const open = change !== null
  const heading = useRef<HTMLHeadingElement>(null)
  const openId = change?.id
  const lastId = useRef(openId)
  // Moving focus to the heading tells screen readers which product is open.
  // On close, focus goes back to that product's row in the table.
  useEffect(() => {
    if (openId) heading.current?.focus()
    else if (lastId.current) {
      document
        .querySelector<HTMLElement>(`[data-review-id="${lastId.current}"]`)
        ?.focus()
    }
    lastId.current = openId
  }, [openId])

  return (
    <section
      aria-label="Review changes"
      aria-hidden={!open}
      inert={!open}
      onKeyDown={(e) => {
        if (e.key === 'Escape') onClose()
      }}
      className={cn(
        'shrink-0 overflow-hidden bg-background duration-300 ease-out motion-reduce:transition-none max-sm:absolute max-sm:inset-y-0 max-sm:right-0 max-sm:z-20',
        // Pushes the table aside as it widens (on phones it covers it instead).
        // Visible at once when opening, so the heading can take focus; hidden
        // only after closing, so it can't be tabbed to while closed
        open
          ? 'visible w-full border-l transition-[width] sm:w-[26rem]'
          : 'invisible w-0 transition-[width,visibility]',
      )}
    >
      {/* A fixed width inside, so the content doesn't reflow while the panel widens */}
      <div className="flex h-full w-full flex-col sm:w-[26rem]">
        {shown ? (
          <DiffBody
            change={shown}
            position={position}
            decisions={decisions}
            onDecide={onDecide}
            onPrevious={onPrevious}
            onNext={onNext}
            onClose={onClose}
            headingRef={heading}
          />
        ) : null}
      </div>
    </section>
  )
}

function DiffBody({
  change,
  position,
  decisions,
  onDecide,
  onPrevious,
  onNext,
  onClose,
  headingRef,
}: Omit<Parameters<typeof DiffPanel>[0], 'change'> & {
  change: Change
  headingRef: Ref<HTMLHeadingElement>
}) {
  const product = change.kind === 'create' ? change.after : change.before
  const lines = diffLines(change)
  const keys = keysOf(change)
  const state = rowState(change, decisions)
  const pending = keys.filter((k) => !(k in decisions))
  // Several changes can be picked one by one; a single one is just the buttons
  const pickable = change.kind === 'update' && keys.length > 1
  const added = lines.filter((l) => l.kind === 'added').length
  const removed = lines.filter((l) => l.kind === 'removed').length
  const whole = change.kind === 'update' ? undefined : decisions[keys[0]]

  // Partly decided: the buttons finish the rest instead of overwriting picks
  const targets = state === 'partial' ? pending : keys
  const verb =
    change.kind === 'create'
      ? { accept: 'Add product', reject: 'Don’t add' }
      : change.kind === 'delete'
        ? { accept: 'Remove product', reject: 'Keep product' }
        : state === 'partial'
          ? { accept: 'Accept the rest', reject: 'Reject the rest' }
          : { accept: 'Accept changes', reject: 'Reject changes' }

  return (
    <>
      <header className="relative flex flex-col gap-1 border-b p-4 pr-12">
        <Button
          variant="ghost"
          size="icon"
          className="absolute top-3 right-3 size-7"
          aria-label="Close"
          onClick={onClose}
        >
          <X />
        </Button>
        <div className="flex items-center gap-2">
          <h3
            ref={headingRef}
            tabIndex={-1}
            className="font-semibold text-foreground outline-none"
          >
            {product.name}
          </h3>
          {change.kind === 'create' ? (
            <Badge
              variant="outline"
              className="border-emerald-500/40 text-emerald-700 dark:text-emerald-400"
            >
              New
            </Badge>
          ) : change.kind === 'delete' ? (
            <Badge
              variant="outline"
              className="border-red-500/40 text-red-700 dark:text-red-400"
            >
              Removed
            </Badge>
          ) : null}
        </div>
        <div className="flex items-center justify-between gap-2">
          <p className="font-mono text-xs text-muted-foreground">
            {product.sku}
          </p>
          <div className="flex items-center gap-1 text-xs text-muted-foreground">
            <span className="tabular-nums">
              {position.index + 1} of {position.total}
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Previous product with changes"
              onClick={onPrevious}
            >
              <ChevronUp />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Next product with changes"
              onClick={onNext}
            >
              <ChevronDown />
            </Button>
          </div>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4">
        <div className="overflow-hidden rounded-md border font-mono text-xs">
          <div className="flex items-center justify-between border-b bg-muted/50 px-3 py-2 text-muted-foreground">
            <span>products/{product.sku}</span>
            <span>
              {added ? (
                <span className="text-emerald-700 dark:text-emerald-400">
                  +{added}
                </span>
              ) : null}{' '}
              {removed ? (
                <span className="text-red-700 dark:text-red-400">
                  −{removed}
                </span>
              ) : null}
            </span>
          </div>
          <table className="w-full border-collapse">
            <tbody>
              {lines.map((line, i) => {
                const decision =
                  line.kind !== 'context'
                    ? line.key
                      ? decisions[line.key]
                      : whole
                    : undefined
                // The side that won't be used fades once decided
                const dropped =
                  (line.kind === 'removed' && decision === 'accepted') ||
                  (line.kind === 'added' && decision === 'rejected')
                return (
                  <tr
                    key={i}
                    className={cn(
                      line.kind === 'added' &&
                        'bg-emerald-500/10 text-emerald-900 dark:text-emerald-200',
                      line.kind === 'removed' &&
                        'bg-red-500/10 text-red-900 dark:text-red-200',
                      line.kind === 'context' && 'text-muted-foreground',
                      dropped && 'opacity-40',
                    )}
                  >
                    {pickable ? (
                      <td className="w-8 pl-3 align-middle">
                        {line.kind === 'added' && line.key ? (
                          <Checkbox
                            className="bg-background"
                            checked={decisions[line.key] === 'accepted'}
                            onCheckedChange={(on) =>
                              onDecide(
                                [line.key!],
                                on === true ? 'accepted' : 'rejected',
                              )
                            }
                            aria-label={`Accept new ${fieldLabel[line.field].toLowerCase()}: ${line.value}`}
                          />
                        ) : null}
                      </td>
                    ) : null}
                    <td
                      aria-hidden
                      className="w-6 py-1.5 pl-3 text-center select-none"
                    >
                      {line.kind === 'added'
                        ? '+'
                        : line.kind === 'removed'
                          ? '−'
                          : ' '}
                    </td>
                    <td className="w-24 py-1.5 pr-2">
                      {fieldLabel[line.field]}
                    </td>
                    <td
                      className={cn(
                        'py-1.5 pr-3 break-words',
                        dropped && 'line-through',
                      )}
                    >
                      <span className="sr-only">
                        {line.kind === 'added'
                          ? 'New: '
                          : line.kind === 'removed'
                            ? 'Old: '
                            : 'Unchanged: '}
                      </span>
                      {line.value}
                      {line.kind === 'added' && line.moved ? (
                        <span className="ml-2 opacity-70">{line.moved}</span>
                      ) : null}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
        {pickable && state !== 'accepted' && state !== 'rejected' ? (
          <p className="mt-3 text-xs text-muted-foreground">
            Tick the changes to keep, or decide them all at once below.
          </p>
        ) : null}
      </div>

      <footer className="flex items-center justify-end gap-2 border-t p-4">
        {state === 'pending' || state === 'partial' ? (
          <>
            {/* On phones the two share the row instead of wrapping */}
            <Button
              variant="outline"
              className="flex-1 sm:flex-none"
              onClick={() => onDecide(targets, 'rejected', true)}
            >
              <X /> {verb.reject}
            </Button>
            <Button
              className="flex-1 sm:flex-none"
              onClick={() => onDecide(targets, 'accepted', true)}
            >
              <Check /> {verb.accept}
            </Button>
          </>
        ) : (
          <>
            <span
              className={cn(
                'mr-auto text-sm',
                state === 'accepted'
                  ? 'text-emerald-700 dark:text-emerald-400'
                  : 'text-muted-foreground',
              )}
            >
              {state === 'accepted'
                ? 'Accepted'
                : state === 'rejected'
                  ? 'Rejected'
                  : `${keys.filter((k) => decisions[k] === 'accepted').length} of ${keys.length} accepted`}
            </span>
            <Button variant="ghost" onClick={() => onDecide(keys, null)}>
              Undo
            </Button>
            <Button variant="outline" onClick={onNext}>
              Next <ChevronDown />
            </Button>
          </>
        )}
      </footer>
    </>
  )
}

import { ChevronRight } from 'lucide-react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { cn } from '#/lib/utils'
import { fields } from './data'
import type { CatalogRow } from './data'
import { changedFields, formatValue, inView, keysOf, rowState } from './diff'
import type { Decisions, View } from './diff'

export interface ReviewMeta {
  decisions: Decisions
  /** Opens the diff panel for a product with changes */
  open: (id: string) => void
}

const getMeta = (table: Table<CatalogRow>) =>
  table.options.meta as unknown as ReviewMeta

/** Products without changes only show up under "All" */
export const rowInView = (row: CatalogRow, decisions: Decisions, view: View) =>
  row.change ? inView(rowState(row.change, decisions), view) : view === 'all'

function ReviewBadge({
  row,
  decisions,
}: {
  row: CatalogRow
  decisions: Decisions
}) {
  if (!row.change) return null
  const state = rowState(row.change, decisions)
  const keys = keysOf(row.change)
  const label =
    state === 'accepted'
      ? 'Accepted'
      : state === 'rejected'
        ? 'Rejected'
        : state === 'mixed'
          ? 'Partly accepted'
          : row.change.kind === 'create'
            ? 'New product'
            : row.change.kind === 'delete'
              ? 'Removal'
              : `${keys.length} change${keys.length === 1 ? '' : 's'}`
  return (
    <Badge
      variant="outline"
      className={cn(
        state === 'pending' || state === 'partial'
          ? 'border-amber-500/50 bg-amber-500/10 text-amber-800 dark:text-amber-300'
          : state === 'accepted'
            ? 'border-emerald-500/40 text-emerald-700 dark:text-emerald-400'
            : 'text-muted-foreground',
      )}
    >
      {label}
    </Badge>
  )
}

export const columns: ColumnDef<CatalogRow>[] = [
  {
    id: 'product',
    header: 'Product',
    accessorFn: (row) => row.product.name,
    filterFn: (row, _id, filter: { view: View; decisions: Decisions }) =>
      rowInView(row.original, filter.decisions, filter.view),
    cell: ({ row, table }) => {
      const { product, change } = row.original
      const name = (
        <span className="flex items-center gap-2 font-medium">
          {product.name}
          {change?.kind === 'update' &&
          changedFields(change).includes('name') ? (
            <span
              title="Changes in this update"
              className="size-1.5 shrink-0 rounded-full bg-amber-500"
            />
          ) : null}
          {change?.kind === 'create' ? (
            <span className="text-xs font-normal text-emerald-700 dark:text-emerald-400">
              new
            </span>
          ) : null}
        </span>
      )
      return (
        <div className="flex min-w-36 flex-col gap-0.5">
          {change ? (
            // A real button, so the panel opens from the keyboard too
            <button
              type="button"
              data-review-id={row.id}
              onClick={(e) => {
                e.stopPropagation()
                getMeta(table).open(row.id)
              }}
              className="rounded-sm text-left outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
              aria-label={`Review changes to ${product.name}`}
            >
              {name}
            </button>
          ) : (
            name
          )}
          <span className="font-mono text-xs text-muted-foreground">
            {product.sku}
          </span>
        </div>
      )
    },
  },
  ...fields
    .filter((f) => f.id !== 'name')
    .map((field): ColumnDef<CatalogRow> => ({
      id: field.id,
      header: () => (
        <span className={cn(field.numeric && 'block text-right')}>
          {field.label}
        </span>
      ),
      cell: ({ row }) => {
        const { product, change } = row.original
        const changing =
          change?.kind === 'update' && changedFields(change).includes(field.id)
        return (
          <span
            className={cn(
              'inline-flex items-center gap-1.5',
              field.numeric && 'w-full justify-end tabular-nums',
              change?.kind === 'delete' && 'text-muted-foreground line-through',
            )}
          >
            {formatValue(field.id, product[field.id])}
            {changing ? (
              // Marks the values the update would change
              <span
                title="Changes in this update"
                className="size-1.5 shrink-0 rounded-full bg-amber-500"
              />
            ) : null}
          </span>
        )
      },
    })),
  {
    id: 'review',
    header: () => <span className="sr-only">Review</span>,
    cell: ({ row, table }) => (
      <div className="flex items-center justify-end gap-1">
        <ReviewBadge row={row.original} decisions={getMeta(table).decisions} />
        {row.original.change ? (
          <ChevronRight className="size-4 text-muted-foreground" />
        ) : null}
      </div>
    ),
  },
]

import { useEffect, useMemo } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  useReactTable,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { ReviewMeta } from './columns'
import { rowState } from './diff'
import type { View } from './diff'
import type { CatalogRow } from './data'

export function CatalogTable({
  rows,
  view,
  openId,
  meta,
}: {
  rows: CatalogRow[]
  view: View
  /** The product whose diff is open, highlighted while the panel shows it */
  openId: string | null
  meta: ReviewMeta
}) {
  // Memoized: a new filter value on every render would recompute the rows
  // each time. It changes with the decisions, so "To review" drops rows as
  // they are decided.
  const columnFilters = useMemo(
    () =>
      view === 'all'
        ? []
        : [{ id: 'product', value: { view, decisions: meta.decisions } }],
    [view, meta.decisions],
  )

  const table = useReactTable({
    data: rows,
    columns,
    getRowId: (row) => row.id,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    state: { columnFilters },
    autoResetPageIndex: false,
    meta,
  })

  const visible = table.getRowModel().rows

  // Stepping through products keeps the open one in view
  useEffect(() => {
    if (openId) {
      document
        .querySelector(`[data-review-id="${openId}"]`)
        ?.scrollIntoView({ block: 'nearest' })
    }
  }, [openId])

  return (
    <div className="max-h-[36rem] min-h-[28rem] min-w-0 flex-1 overflow-auto">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id} className="hover:bg-transparent">
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id}>
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {visible.length ? (
            visible.map((row) => {
              const { change } = row.original
              const state = change ? rowState(change, meta.decisions) : null
              const toReview = state === 'pending' || state === 'partial'
              return (
                <TableRow
                  key={row.id}
                  data-state={row.id === openId ? 'selected' : undefined}
                  onClick={change ? () => meta.open(row.id) : undefined}
                  className={cn(
                    change && 'cursor-pointer',
                    // Rows waiting for review stand out; everything else stays quiet
                    toReview &&
                      'bg-amber-500/[0.07] shadow-[inset_3px_0_0_var(--color-amber-500)] hover:bg-amber-500/[0.12]',
                    state === 'rejected' && 'text-muted-foreground',
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="py-2.5">
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              )
            })
          ) : (
            <TableRow className="hover:bg-transparent">
              <TableCell
                colSpan={columns.length}
                className="h-24 text-center text-muted-foreground"
              >
                {view === 'review'
                  ? 'Everything has been reviewed.'
                  : `No ${view} changes.`}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}

import { useState } from 'react'
import { CircleCheck, FileDiff } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils'
import { changes, rows, unchanged } from './data'
import { CatalogTable } from './data-table'
import { DiffPanel } from './diff-panel'
import { rowInView } from './columns'
import {
  WHOLE,
  apply,
  changeKey,
  decide,
  keysOf,
  rowState,
  tally,
} from './diff'
import type { Decision, Decisions, View } from './diff'

const views: { id: View; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'review', label: 'To review' },
  { id: 'accepted', label: 'Accepted' },
  { id: 'rejected', label: 'Rejected' },
]

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

// The order the panel steps through: products with changes, as the table lists them
const reviewOrder = rows.filter((r) => r.change).map((r) => r.id)
const changeById = new Map(changes.map((c) => [c.id, c]))

const needsReview = (id: string, decisions: Decisions) => {
  const state = rowState(changeById.get(id)!, decisions)
  return state === 'pending' || state === 'partial'
}

/** The next product still to review after `from`, wrapping around */
function nextToReview(from: string | null, decisions: Decisions) {
  const start = from ? reviewOrder.indexOf(from) : -1
  for (let i = 1; i <= reviewOrder.length; i++) {
    const id = reviewOrder[(start + i) % reviewOrder.length]
    if (needsReview(id, decisions)) return id
  }
  return null
}

/** What applying would do, record by record */
function summarize(decisions: Decisions) {
  const accepted = (k: string) => decisions[k] === 'accepted'
  return {
    changes: tally(changes, decisions).accepted,
    updated: changes.filter(
      (c) => c.kind === 'update' && keysOf(c).some(accepted),
    ).length,
    added: changes.filter(
      (c) => c.kind === 'create' && accepted(changeKey(c.id, WHOLE)),
    ).length,
    removed: changes.filter(
      (c) => c.kind === 'delete' && accepted(changeKey(c.id, WHOLE)),
    ).length,
    catalog: unchanged.length + apply(changes, decisions).length,
  }
}

export function ChangeReviewDemo() {
  const [decisions, setDecisions] = useState<Decisions>({})
  const [view, setView] = useState<View>('all')
  const [openId, setOpenId] = useState<string | null>(null)
  const [applied, setApplied] = useState<Decisions | null>(null)

  const counts = tally(changes, decisions)
  const rowCount = (v: View) =>
    rows.filter((r) => r.change && rowInView(r, decisions, v)).length
  const pendingKeys = changes.flatMap(keysOf).filter((k) => !(k in decisions))

  function decideKeys(
    keys: string[],
    decision: Decision | null,
    advance = false,
  ) {
    const next = decide(decisions, keys, decision)
    setDecisions(next)
    // After a decision in the panel, go straight to the next product to review
    if (advance) setOpenId(nextToReview(openId, next))
  }

  const step = (by: 1 | -1) => {
    const i = openId ? reviewOrder.indexOf(openId) : -1
    setOpenId(reviewOrder[(i + by + reviewOrder.length) % reviewOrder.length])
  }

  if (applied) {
    const result = summarize(applied)
    return (
      <div className="flex flex-col items-start gap-3 rounded-md border p-6">
        <CircleCheck className="size-6 text-emerald-600" />
        <div>
          <p className="font-medium">
            Applied {plural(result.changes, 'change')}
          </p>
          <p className="text-sm text-muted-foreground">
            {plural(result.updated, 'product')} updated, {result.added} added,{' '}
            {result.removed} removed. The catalog now has{' '}
            {plural(result.catalog, 'product')}. Rejected and pending changes
            were left out.
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={() => {
            setApplied(null)
            setDecisions({})
            setView('all')
          }}
        >
          Start over
        </Button>
      </div>
    )
  }

  const openChange = openId ? (changeById.get(openId) ?? null) : null
  const toReview = rowCount('review')

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
          <FileDiff className="size-4 text-muted-foreground" />
          <span className="font-medium">Supplier price list + stocktake</span>
          <span className="text-muted-foreground">
            touches {plural(changes.length, 'product')} of {rows.length}
          </span>
        </p>
        <Button
          size="sm"
          disabled={toReview === 0}
          onClick={() => setOpenId(nextToReview(null, decisions))}
        >
          {toReview ? `Review ${plural(toReview, 'product')}` : 'All reviewed'}
        </Button>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-2">
        <div
          role="group"
          aria-label="Show rows"
          className="inline-flex rounded-md border p-0.5"
        >
          {views.map((v) => (
            <button
              key={v.id}
              type="button"
              aria-pressed={view === v.id}
              onClick={() => setView(v.id)}
              className="flex h-7 items-center gap-1.5 rounded px-2.5 text-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:bg-muted aria-pressed:text-foreground"
            >
              {v.label}
              <span className="text-xs tabular-nums">
                {v.id === 'all' ? rows.length : rowCount(v.id)}
              </span>
            </button>
          ))}
        </div>
        <div className="flex gap-2">
          <Button
            variant="ghost"
            size="sm"
            disabled={!pendingKeys.length}
            onClick={() => decideKeys(pendingKeys, 'rejected')}
          >
            Reject the rest
          </Button>
          <Button
            variant="ghost"
            size="sm"
            disabled={!pendingKeys.length}
            onClick={() => decideKeys(pendingKeys, 'accepted')}
          >
            Accept the rest
          </Button>
        </div>
      </div>

      {/* The table scrolls inside this frame, and the panel opens at its right,
          pushing the table aside. The panel is never taller than the frame, so
          its buttons are always in view. */}
      <div className="relative flex overflow-hidden rounded-md border">
        <CatalogTable
          rows={rows}
          view={view}
          openId={openId}
          meta={{ decisions, open: setOpenId }}
        />
        <DiffPanel
          change={openChange}
          position={{
            index: openId ? reviewOrder.indexOf(openId) : 0,
            total: reviewOrder.length,
          }}
          decisions={decisions}
          onDecide={decideKeys}
          onPrevious={() => step(-1)}
          onNext={() => step(1)}
          onClose={() => setOpenId(null)}
        />
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3">
        <p aria-live="polite" className="text-sm text-muted-foreground">
          <span className="text-emerald-700 dark:text-emerald-400">
            {counts.accepted} accepted
          </span>
          {' · '}
          <span className={cn(counts.rejected > 0 && 'text-destructive')}>
            {counts.rejected} rejected
          </span>
          {' · '}
          {counts.pending} to review
        </p>
        <Button
          size="sm"
          variant={counts.pending ? 'outline' : 'default'}
          disabled={counts.accepted === 0}
          onClick={() => setApplied(decisions)}
        >
          Apply {plural(counts.accepted, 'change')}
        </Button>
      </div>
    </div>
  )
}
